+            // Only the recovered owner may finish processing the event.
+            yield* markWebhookEventProcessed(recovered);
+            yield* releaseWebhookEventClaim(original);
+            expect(
+              yield* claimWebhookEvent({
+                eventId,
+                eventType: 'checkout.session.completed',
