+    const eventId = `evt_test_${randomUUID()}`;
+    try {
+      await Effect.runPromise(
+        Effect.gen(function* () {
+          const original = yield* claimEvent(eventId);
+          const [row] = yield* Effect.promise(() =>
+            database
